using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class NurseHairWeightFit {
 const string Folder=NurseVisualOptimization.Folder;const string Out=NurseVisualOptimization.Out;
 static float Hair(BoneWeight w,Transform[] bones){int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] values={w.weight0,w.weight1,w.weight2,w.weight3};float sum=0;for(int i=0;i<4;i++)if(bones[ids[i]].name.StartsWith("Hair_"))sum+=values[i];return sum;}
 public static void Run(){var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/EntityStudioGenerated/RebirthNurseNative/RebirthNurse_Authoring.prefab");var renderer=model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0");var bones=renderer.bones;int head=Array.FindIndex(bones,b=>b.name=="Head");var bodyNames=new HashSet<string>{"Hips","Spine","Spine1","Spine2","Spine3","Neck","LeftShoulder","RightShoulder"};var body=Enumerable.Range(0,bones.Length).Where(i=>bodyNames.Contains(bones[i].name)).ToArray();if(head<0||body.Length<4)throw new Exception("Expected native torso/head bones missing");var albedo=new Texture2D(2,2,TextureFormat.RGBA32,false,true);albedo.LoadImage(File.ReadAllBytes(Out+"/Atlas_Albedo.png"));var reports=new List<string>();
  foreach(int count in new[]{20000,9500,3000}){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/Blender_"+count+".asset");var vertices=mesh.vertices;var triangles=mesh.triangles;var uv=mesh.uv;var baseline=AssetDatabase.LoadAssetAtPath<Mesh>(Folder+"/"+NurseSurfaceFinish.MeshBaselinePrefix+count+".asset");if(baseline==null||!baseline.uv.SequenceEqual(uv)||!baseline.triangles.SequenceEqual(triangles))throw new Exception("Hair weight baseline does not match mesh topology/UVs");var weights=baseline.boneWeights;var points=vertices.Select(renderer.transform.TransformPoint).ToArray();var pin=new bool[vertices.Length];var face=new bool[vertices.Length];int before=0,changed=0;
   for(int i=0;i<vertices.Length;i++){var p=points[i];var color=albedo.GetPixelBilinear(uv[i].x,uv[i].y);bool blue=color.b>color.r*1.13f&&color.g>color.r*1.05f;face[i]=p.y>1.50f&&p.y<1.69f&&Mathf.Abs(p.x)<.065f&&p.z>.025f;pin[i]=blue||p.y<1.25f||face[i]||p.y>1.685f;}
   // UV seams share the same constraint so adjacent surface copies cannot separate.
   foreach(var group in Enumerable.Range(0,vertices.Length).GroupBy(i=>new Vector3Int(Mathf.RoundToInt(points[i].x*100000),Mathf.RoundToInt(points[i].y*100000),Mathf.RoundToInt(points[i].z*100000))))if(group.Any(i=>pin[i]))foreach(int i in group)pin[i]=true;
   for(int i=0;i<vertices.Length;i++){if(!pin[i]||Hair(weights[i],bones)<.0001f)continue;before++;if(face[i]||points[i].y>1.685f)weights[i]=new BoneWeight{boneIndex0=head,weight0=1};else{var nearest=body.OrderBy(id=>(bones[id].position-points[i]).sqrMagnitude).Take(2).ToArray();float a=1/Mathf.Pow(Mathf.Max(.01f,Vector3.Distance(bones[nearest[0]].position,points[i])),4),b=1/Mathf.Pow(Mathf.Max(.01f,Vector3.Distance(bones[nearest[1]].position,points[i])),4);weights[i]=new BoneWeight{boneIndex0=nearest[0],weight0=a/(a+b),boneIndex1=nearest[1],weight1=b/(a+b)};}changed++;}
   // Previously rigid hanging front locks use the same accepted native chain.
   // Untouched-source hair colour separates blond locks from skin and blue fabric.
   var addHair=new bool[vertices.Length];var strength=new float[vertices.Length];int added=0;for(int k=0;k<vertices.Length;k++){strength[k]=Hair(weights[k],bones);var p=points[k];var c=albedo.GetPixelBilinear(uv[k].x,uv[k].y);bool blond=c.g>c.b*1.12f&&c.r<c.g*1.45f&&c.r>c.g*.95f;addHair[k]=!pin[k]&&strength[k]<.05f&&p.y>1.25f&&p.y<1.53f&&Mathf.Abs(p.x)>.075f&&Mathf.Abs(p.x)<.205f&&p.z>-.105f&&p.z<.14f&&blond;if(addHair[k])strength[k]=Mathf.SmoothStep(0,1,Mathf.Clamp01((1.68f-p.y)/.10f))*.85f;}
   var seams=Enumerable.Range(0,vertices.Length).GroupBy(k=>new Vector3Int(Mathf.RoundToInt(points[k].x*100000),Mathf.RoundToInt(points[k].y*100000),Mathf.RoundToInt(points[k].z*100000))).Select(g=>g.ToArray()).ToArray();foreach(var group in seams)if(group.Any(k=>addHair[k])&&!group.Any(k=>pin[k])){float value=group.Max(k=>strength[k]);foreach(int k in group){if(Hair(weights[k],bones)<.05f)addHair[k]=true;strength[k]=Mathf.Max(strength[k],value);}}
   for(int pass=0;pass<3;pass++){var next=(float[])strength.Clone();for(int t=0;t<triangles.Length;t+=3)for(int edge=0;edge<3;edge++){int a=triangles[t+edge],b=triangles[t+(edge+1)%3];if(addHair[a])next[a]=Mathf.Min(next[a],strength[b]+.20f);if(addHair[b])next[b]=Mathf.Min(next[b],strength[a]+.20f);}strength=next;foreach(var group in seams)if(group.Any(k=>addHair[k])){float value=group.Min(k=>strength[k]);foreach(int k in group)if(addHair[k])strength[k]=value;}}
   for(int k=0;k<vertices.Length;k++)if(addHair[k]&&strength[k]>.001f){float f=Mathf.Clamp((1.69f-points[k].y)/.08f,0,4);int a=Mathf.Min(3,Mathf.FloorToInt(f));float t=f-a;string n0="Hair_Back_Left"+(a==0?"":a.ToString()),n1="Hair_Back_Left"+(a+1);int id0=Array.FindIndex(bones,b=>b.name==n0),id1=Array.FindIndex(bones,b=>b.name==n1);if(id0<0||id1<0)throw new Exception("Expected native hair chain missing");weights[k]=new BoneWeight{boneIndex0=id0,weight0=strength[k]*(1-t),boneIndex1=id1,weight1=strength[k]*t,boneIndex2=head,weight2=1-strength[k]};added++;}
   int after=Enumerable.Range(0,vertices.Length).Count(i=>pin[i]&&Hair(weights[i],bones)>.0001f);if(after!=0)throw new Exception("Hair influence remains on pinned cloth/face");foreach(var w in weights)if(Mathf.Abs(w.weight0+w.weight1+w.weight2+w.weight3-1)>.001f)throw new Exception("Hair weight normalization failed");mesh.boneWeights=weights;EditorUtility.SetDirty(mesh);if(!vertices.SequenceEqual(mesh.vertices)||!triangles.SequenceEqual(mesh.triangles)||!uv.SequenceEqual(mesh.uv))throw new Exception("Weight fit changed geometry");reports.Add(count+": pinned cloth/face/crown vertices with hair influence before="+before+" after="+after+"; corrected="+changed+"; previously rigid front-lock vertices weighted="+added+"; geometry/UV/triangles unchanged; normalized weights PASS.");
  }
  AssetDatabase.SaveAssets();File.WriteAllLines(Out+"/hair-weight-fit.txt",reports.Concat(new[]{"Uses the accepted existing Hair_Back_Left chain; no bones, skeleton transforms, colliders, animation controller or runtime code added. This removes stray influences, not a claim of independent multi-chain flow or in-game simulation validation."}));
 }
}
